  }
  function nextLesson(){if(chapter<lessons.length-1)setChapter(chapter+1,true);else{lessonPlaying=false;audio.pause();renderLesson(1);$('lesson-play').textContent='讲解完成，进入算法回放 →';}}
  function switchView(view){
