"""Validate the offline course bundle using only the Python standard library."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def js_object(path, prefix):
    content = path.read_text(encoding='utf-8')
    if not content.startswith(prefix):
        raise AssertionError(f'Unexpected prefix in {path.name}')
    return json.loads(content[len(prefix):].strip().removesuffix(';'))


def verify():
    lessons = json.loads((ROOT / 'lessons.json').read_text(encoding='utf-8'))
    manifest = json.loads((ROOT / 'media_manifest.json').read_text(encoding='utf-8'))
    data = js_object(ROOT / 'data.js', 'window.CHAN_DATA=')
    assert len(lessons) == len(manifest['chapters']) == 13
    assert manifest['script_sha256'] == hashlib.sha256((ROOT/'lessons.json').read_bytes()).hexdigest()
    for i, chapter in enumerate(manifest['chapters']):
        assert chapter['id'] == lessons[i]['id']
        assert chapter['duration'] > 10
        assert (ROOT / chapter['audio']).stat().st_size > 1000
    assert 300 < manifest['video_seconds'] < 480
    assert (ROOT / manifest['video']).stat().st_size > 1_000_000
    assert data['meta']['synthetic'] is True
    assert data['meta']['execution_allowed'] is False
    assert len(data['bars']) == len(data['snapshots']) == 378
    for i, snapshot in enumerate(data['snapshots']):
        assert snapshot['as_of'] == i
        assert snapshot['input_bars'] == i + 1
        for key in ('fractals', 'strokes', 'segments', 'centers'):
            for item in snapshot[key]:
                for field in ('confirmed_at', 'available_at'):
                    if item.get(field) is not None:
                        assert item[field] <= i, (i,key,field)
    assert data['snapshots'][94]['signal_states'] == {}
    assert data['snapshots'][109]['signal_states']['third_buy_candidate:95'] == 'candidate'
    assert data['snapshots'][155]['signal_states']['third_buy_candidate:95'] == 'invalidated'
    for required in ('index.html','style.css','app.js','lessons.js','media.js','data.js',
                     'README.md','chanlun_algorithm.py','chanlun_engine.py','build_chart_data.py',
                     '打开讲解与算法图.cmd','缠论大白话复习总结.pdf'):
        assert (ROOT / required).is_file(), required
    return {'lessons':len(lessons),'video_seconds':manifest['video_seconds'],
            'bars':len(data['bars']),'causal_snapshots':len(data['snapshots']),
            'event_count':len(data['events']),
            'video_sha256':hashlib.sha256((ROOT/manifest['video']).read_bytes()).hexdigest(),
            'verified':True}


if __name__ == '__main__':
    print(json.dumps(verify(),ensure_ascii=False,indent=2))

